from collections import Counter
from prepare import *
# Source-review judgments, all provisional and sense-qualified.
DECISIONS={
'L01':('contextual_increment_support','Winslow defines the target as the same creeper as aṭampu. Lexicon koṭi sense 1 is creeper; the kōṭi homographs have other senses. DEDR 65 independently lists the botanical forms aṭampu and aṭappaṅ-koṭi; 2050 groups the creeper sense of koṭi. This supports the exact short-o candidate and leaves the long-o alternative unsupported for this source sense.',[('aṭampu','',44),('koṭi','',1133)],['65','2050'],'Dravidian comparative botanical entries; no authenticated whole-compound ancestry'),
'L02':('contextual_increment_support','Winslow calls the target the castor plant seed. Lexicon koṭṭai sense 1 means seed or kernel, while kōṭṭai has capacity and fort senses. The āmaṇakku entry is starred and gives āmaṇda. DEDR 360 includes Sanskrit comparison outside its Dravidian list. The native-versus-borrowed status of the plant name remains unresolved.',[('āmaṇakku','',234),('koṭṭai','',1131)],['360','2069'],'Printed Sanskrit comparison retained; DEDR membership alone cannot certify native ancestry'),
'L03':('contextual_increment_support','Winslow explicitly gives an ear of kampu. The relevant Lexicon entries are kampu² millet and katir¹ sense 5 ear of grain. Pole and ray homographs are different senses. DEDR 1242 lists millet and kampam-pul, with a Sanskrit comparison; 1194 separately groups the ear-of-grain sense.',[('kampu','²',728),('katir','¹',712)],['1242','1194'],'Millet sense selected; the Sanskrit comparison prevents a simple native label'),
'L04':('contextual_increment_support','Winslow defines boiled varaku. Lexicon varaku and cōṟu¹ sense 1 supply millet and boiled-food senses. DEDR 5260 and 2897 group those senses; 5260 also records Indo-Aryan comparisons. No original poetic witness for this whole compound was inspected.',[('varaku','',3507),('cōṟu','¹',1679)],['5260','2897'],'Comparative sense support; direction of borrowing remains unresolved'),
'L05':('printed_boundary_and_context_support','The Lexicon prints pīrkkaṅ-kūṭu with an explicit pīrkku etymology and a Cilappatikāram 3,26 commentary citation. Winslow calls the target a dry pod. DEDR 4224 supplies the gourd forms and 1883 the receptacle sense, while also noting a Sanskrit comparison. The commentary citation is not an independently inspected ancient attestation.',[('pīrkkaṅ-kūṭu','',2736)],['4224','1883'],'Source-supported gourd sense; complete ancestry and citation dating remain open'),
'L06':('contextual_increment_support','Winslow calls the target one of seven islands. DEDR 3408 prints teṅku and teṅkam for coconut tree, directly documenting an am form in this lexical family. Its exact tīvu match in entry 3268 means sweetness, not island. Lexicon tīvu¹ gives dvīpa for island; the relevant second noun therefore has explicit Sanskrit etymological evidence.',[('teṅku','',2028),('tīvu','¹',1951),('tīvu','³',1951)],['3408','3268'],'Coconut comparative family and Sanskrit-derived island sense must remain separate'),
'L07':('contextual_increment_support','Winslow defines boiled kampu. Lexicon kampu² millet and cōṟu¹ boiled rice are the relevant senses. DEDR 1242 and 2897 support these lemma senses, with the millet entry retaining its Sanskrit comparison. This is contextual support for the printed compound, not a general increment admission rule.',[('kampu','²',728),('cōṟu','¹',1679)],['1242','2897'],'Sense-qualified comparative support; whole-compound origin unresolved'),
'L08':('increment_candidate_contradicted_by_source_sense','Winslow defines ten parts and refers to tacāṅkam. The proposed pattaṅ plus kam increment analysis has no relevant kam sense among the inspected entries. Pattu¹ is ten; aṅkam¹ means limb or part and is starred with Sanskrit aṅga. The inherited patt plus aṅkam boundary fits the printed ten-parts sense; this is a source-backed regression diagnosis, not a new segmentation submission.',[('pattu','¹',2466),('aṅkam','¹',20)],['3918'],'Numeral plus Sanskrit-derived part; not two native picture nouns'),
'L09':('homograph_senses_separated','Winslow gives darkness. The Lexicon supplement karuvari on p.4125 gives karvarī and darkness; p.764 karu-vari means dark lines in the eye. DEDR 1278 supports black karu and karumai, but cannot move that etymology to the differently glossed darkness entry.',[('karu-vari','',764),('karuvari','',4125)],['1278'],'Printed karvarī etymology and Dravidian black family remain distinct'),
'L10':('homograph_senses_separated','Winslow gives heat or hot season. DEDR 5517 includes vēṉil in the heat family. Lexicon p.3847 distinguishes heat/spring from decoration/beauty and prints different roman vowel lengths although the Tamil headword is shared. We preserve that edition discrepancy without introducing a vowel substitution.',[('veṉil','¹',3847),('vēṉil','²',3847)],['5517'],'Heat family has comparative support; no ancestry inferred for beauty homograph'),
'L11':('homograph_senses_separated','Winslow gives the treasure of chank shape. Lexicon caṅka-niti¹ is the treasure with Tēvāram 1230,10 citation; caṅkaniti² is a plant and cites Winslow. DEDR 2274 matches caṅkam only in the armpit sense, which supplies no support for the treasure sense. The starred Winslow parent includes several Sanskrit comparisons.',[('caṅka-niti','¹',1222),('caṅkaniti','²',1222)],['2274'],'Marked parent and wrong-sense DEDR hit retained; no native certification'),
'L12':('homograph_senses_separated','Winslow marks the principal foreign and defines redemption or cancellation money. Lexicon caṇṭivāḷam¹ repeats that definition, cites Winslow and gives Kannada caṇḍivāḷa; caṇṭi-vāḷam² means leg fetters. DEDR vāḷam sword is a different sense. The two dictionaries here share an explicit citation and do not independently attest the transaction term.',[('caṇṭivāḷam','¹',1245),('caṇṭi-vāḷam','²',1245)],['5376'],'Foreign label and Kannada comparison; direction and history need specialist review'),
'L13':('homograph_senses_separated','Winslow gives grain price. Lexicon aka-vilai² gives that sense and cites aḵkam, while aka-v-ilai¹ is an inner petal. DEDR akam inside and ilai leaf belong to the latter comparison, not proof of a native grain noun; vilai price is separately supported in 5421. The starred price entry and its first-member history remain explicit.',[('aka-v-ilai','¹',15),('aka-vilai','²',15),('vilai','',3715)],['7','5421'],'Price sense selected; grain first-member ancestry unresolved'),
'L14':('homograph_senses_separated','Winslow nests great austerities under a starred mā adjective explicitly contracted from Sanskrit Mahat. Lexicon mā-tavam² gives mahat plus tapas; mātavam¹ gives mādhava and spring. DEDR 4786 separately groups mā great with Dravidian forms. That comparison does not cancel the source-specific Sanskrit derivation of this compound.',[('mātavam','¹',3155),('mā-tavam','²',3155),('mā','⁴',3142),('tavam','¹',1791)],['4786'],'Competing etymological traditions require specialist adjudication'),
'L15':('nominal_sense_supported_label_conflict_retained','Winslow labels cettal a verbal noun but gives dried-fruit and vegetable senses and explicitly calls the target dry murukku wood. The Lexicon labels cettal a noun with those material senses. DEDR 2770 groups dried vegetable material separately from 2426 dying; 4981 groups the tree. This supplies a nominal-sense review target while leaving the frozen exact-noun exclusion unchanged.',[('cettal','',1585),('murukku','³',3279)],['2770','4981'],'Material noun evidence retained; botanical species and first-member history remain qualified'),
'L16':('contextual_increment_support','Winslow explicitly identifies the flower as belonging to its murukku tree. Lexicon murukku³ gives botanical senses and pū³ sense 1 gives flower; the killing and earth homographs are excluded for this source sense. DEDR 4981 distinguishes Tamil palas and Malayalam coral-tree names and records a Munda comparison; 4345 groups flower with a queried Sanskrit comparison. Species identity and lexical ancestry need specialist review.',[('murukku','³',3279),('pū','³',2819)],['4981','4345'],'Botanical comparative evidence with cross-family notes; no complete native classification')}
def main():
 packets=read(RAW/'source-packets-v2.json');out=[]
 for p in packets:
  status,judgment,tlrefs,dnums,origin=DECISIONS[p['case_id']]
  tl=[]
  for form,hom,page in tlrefs:
   found=[x for x in p['lexicon_entries'] if (x['entry']['translit'],x['entry']['hom'],x['entry']['page'])==(form,hom,page)]
   assert len(found)==1,(p['case_id'],form)
   tl.append(found[0])
  de=[d for d in p['dedr_entries'] if d['number'] in dnums];assert len({d['number'] for d in de})==len(dnums)
  out.append(dict(case_id=p['case_id'],stratum=p['stratum'],source_disposition=status,judgment=judgment,
   origin_scope=origin,selected_lexicon_senses=tl,selected_dedr_entries=de,
   winslow_witness=p['winslow_witness'],earliest_attestation='Not verified; printed citations retained in original witnesses',
   specialist_adjudication=False,prior_candidates_unchanged=True,prior_scorer_eligibility_unchanged=True,
   morphology_status='unresolved_outside_source_specific_observations'))
 save(RAW/'source-review-v1.json',out)
 summary=dict(cases=len(out),dispositions=dict(Counter(r['source_disposition'] for r in out)),
  selected_lexicon_sense_references=sum(len(r['selected_lexicon_senses']) for r in out),
  selected_dedr_case_references=sum(len(r['selected_dedr_entries']) for r in out),
  unique_selected_dedr_entries=len({d['number'] for r in out for d in r['selected_dedr_entries']}),
  harvested_lexicon_case_records=sum(len(r['lexicon_entries']) for r in packets),
  harvested_dedr_case_records=sum(len(r['dedr_entries']) for r in packets),
  specialist_adjudications=0,source_specific_sense_decisions=True,
  new_extraction_runs=0,changed_candidate_flags=0,new_confirmation_access=0)
 save(PKG/'results-v1.json',summary);print(json.dumps(summary))
if __name__=='__main__':main()
